'use client'
import React, {useState, CSSProperties, use } from 'react';

const noMessages: string[] = ["Are you sure?", "Think again!", "Reconsider?", "Last chance!", "Surely not?", "You're breaking my heart", "Have a heart!", "Don't be cold", "Change your mind?", "No isn't an option!"];
const activities: string[] = ['Dinner Date', 'Brunch', 'Shopping', 'Explore', 'Simple Walk', 'Surprise Me'];
const getLocalDateString = (date: Date): string => {
  const offset = date.getTimezoneOffset();
  const localDate = new Date(date.getTime() - offset * 60_000);
  return localDate.toISOString().slice(0, 10);
};
const today = getLocalDateString(new Date());

const isDateOnOrAfterToday = (dateString: string): boolean => {
  if (!dateString) return false;
  return dateString >= today;
};

export default function Home() {
  const [screen, setScreen] = useState<number>(1)
  const [noClickCount, setNoClickCount] = useState<number>(0)
  const [selectedDate, setSelectedDate] = useState('')
  const [startTime, setStartTime] = useState('09:00')
  const [endTime, setEndTime] = useState('10:00')
  const [activity, setActivity] = useState('')
  const [name, setName] = useState('')
  const [isSending, setIsSending] = useState<boolean>(false)
  const [showMessage, setShowMessage] = useState<boolean>(false)

  const handleNoClick = (): void => {
    if (noClickCount <10) {
      setNoClickCount((prev) => prev +1)
    }
  }

  const handleDateChange = (value: string): void => {
    if (!value) {
      setSelectedDate('');
      return;
    }

    if (!isDateOnOrAfterToday(value)) {
      setSelectedDate('');
      alert('Please choose a date today or later.');
      return;
    }

    setSelectedDate(value);
  }

  const handleDateContinue = (): void => {
    if (!isDateOnOrAfterToday(selectedDate)) {
      alert('Please choose a date today or later.');
      return;
    }

    setScreen(4);
  }

  async function handleBooking(): Promise<void> {
    setIsSending(true)
    try{
      const response = await fetch('/api/notify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ event: activity, date: selectedDate, start_time: startTime, end_time: endTime,  name: name}),
      })
      if (response.ok){
        setScreen(6);
      } else {
        alert('Something went wrong 💀🥀 Its probably because the free tier has ran out of free email quota whoops, contact me directly instead sorry')
      }
    } catch (error) {
      alert('Network error')
    } finally {
      setIsSending(false)
    }
  }

  return (
    <main style={styles.container}>
      <div style={styles.card}>
        
        {/* Screen 1: Proposal */}
        {screen === 1 && (
          <div style={styles.layout}>
            <h2 style={styles.title}>Will you go out with me?</h2>
            {noClickCount > 0 && noClickCount < 10 && (
              <img src="data:image/gif;base64," alt="" width="436" height="640" />
            )}
            {noClickCount < 1 && (
              <img src="data:image/gif;base64," alt="" width="640" height="518" />              
            )}
            {noClickCount > 9 && (
              <img src="data:image/png;base64," alt="" width="512" height="512" />
            )}
            <div style={styles.btnContainer}>
              <button 
                style={{
                  ...styles.btn,
                  transform: `scale(${1 + noClickCount * 0.2})`,
                  transformOrigin: 'center',
                  minWidth: '100px',
                }}
                onClick={() => setScreen(2)}
              >
                Yes!
              </button>
              
              {noClickCount < 10 && (
                <button 
                  style={{
                    ...styles.btn,
                    ...styles.btnNo,
                    transform: `scale(${Math.max(0.3, 1 - noClickCount * 0.08)})`,
                    transformOrigin: 'center',
                    minWidth: '100px',
                  }}
                  onClick={handleNoClick}
                >
                  No
                </button>
              )}
            </div>
            {noClickCount > -1 && (
              <p style={styles.noMsg}>{noMessages[noClickCount - 1] || ""}</p>
            )}
            
          </div>
        )}

        {/* Screen 2: Yay */}
        {screen === 2 && (
          <div>
            <h2 style={styles.title}>I'm so happy you said yes! 🎉💖</h2>
            <img src="data:image/jpeg;base64," alt="" width="736" height="981" />
            <button style={styles.btn} onClick={() => setScreen(3)}>
              Press to continue
            </button>
          </div>
        )}

        {/* Screen 3: Date Picker */}
        {screen === 3 && (
          <div>
            <h2 style={styles.title}>Pick a Date 🗓️</h2>
            <img src="data:image/gif;base64," alt="" width="640" height="518" />
            <input 
              type="date" 
              min={today}
              value={selectedDate}
              style={styles.dateInput}
              onChange={(e) => handleDateChange(e.target.value)}
            />
            <br />
            <button 
              style={styles.btn}
              disabled={!selectedDate}
              onClick={handleDateContinue}
            >
              Continue
            </button>
          </div>
        )}

        {/* Screen 4: Activity Selection */}
        {screen === 4 && (
          <div>
            <h2 style={styles.title}>What would you like to do?</h2>
            <img src="data:image/jpeg;base64," alt="" width="497" height="402" />
            <div style={styles.grid}>
              {activities.map((item) => (
                <button
                  key={item}
                  style={{
                    ...styles.optionBtn,
                    ...(activity === item ? styles.selectedBtn : {})
                  }}
                  onClick={() => setActivity(item)}
                >
                  {item}
                </button>
              ))}
            </div>
            <button 
              style={styles.btn}
              disabled={!activity}
              onClick={() => setScreen(5)}
            >
              Continue
            </button>
          </div>
        )}

        {/* Screen 5: Name */}
        {screen === 5 && (
          <div>
            <h2 style={styles.title}>What name do you want this booking to be under?</h2>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              style={styles.input}
              placeholder="Enter your name"
            />
            <button
              style={styles.btn}
              disabled={!name || isSending}
              onClick={handleBooking}
            >
              {isSending ? 'Sending...' : 'Lock it in'}
            </button>
          </div>
        )}


        {/* Screen 6: Confirmation */}
        {screen === 6 && (
          <div>
            <h2 style={styles.title}>It's a Date! ✨</h2>
            <p>Your choices have been sent!</p>
            <img src="data:image/png;base64," alt="" width="512" height="512" />
            <button style={styles.btn} onClick={() => setShowMessage(true)}>
              1 New Message 💌
            </button>
            {showMessage && (
              <p style={styles.cuteMsg}>
                you're really cute no matter what. don't let anyone tell you any different, okay? you make every ordinary day feel special. today and every day, i celebrate you and us. xoxo debcaf
              </p>
            )}
          </div>
        )}

      </div>
    </main>
  );
}

const styles: Record<string, CSSProperties> = {
  container: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    minHeight: '100vh',
    backgroundColor: '#fff0f3',
    fontFamily: 'Marker Felt, fantasy',
    color: '#590d22',
  },
  card: {
    background: 'white',
    padding: '2.5rem',
    borderRadius: '20px',
    boxShadow: '0 10px 25px rgba(255, 182, 193, 0.4)',
    textAlign: 'center',
    maxWidth: '420px',
    width: '90%',
  },
  layout: {
    display: 'flex',
    flexDirection: 'column',
    height: '100%',
    minHeight: '360px'
  },
  title: {
    margin: '0 0 auto',
    fontSize: '2rem',
    lineHeight: '1.5',
    fontFamily: 'Marker Felt, fantasy',
  },
  btnContainer: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    gap: '28px',
    marginTop: '20px',
    flexWrap: 'wrap',
  },
  btn: {
    backgroundColor: '#ff4d6d',
    color: 'white',
    border: 'none',
    padding: '12px 24px',
    fontSize: '1rem',
    borderRadius: '12px',
    cursor: 'pointer',
    transition: 'transform 0.2s, background-color 0.2s',
    marginTop: '50px',
    marginLeft: '20px',
    marginRight: '20px',
  },
  btnNo: {
    backgroundColor: '#6c757d',
  },
  noMsg: {
    marginTop: '100px',
    color: '#c9184a',
    fontStyle: 'italic',
    fontSize: '2rem',
  },
  dateInput: {
    padding: '10px',
    fontSize: '1rem',
    margin: '15px 0',
    borderRadius: '8px',
    border: '1px solid #ffb3c1',
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '10px',
    margin: '20px 0',
  },
  optionBtn: {
    background: '#fff0f3',
    color: '#590d22',
    border: '2px solid #ffb3c1',
    padding: '10px',
    borderRadius: '8px',
    cursor: 'pointer',
  },
  selectedBtn: {
    background: '#ff4d6d',
    color: 'white',
  },
  cuteMsg: {
    marginTop: '20px',
    fontWeight: 'bold',
    color: '#ff4d6d',
  }
};
